#!/bin/sh
# Rebuild the two bundles from the sources. theme.js stays separate: it must load blocking in <head>.
set -e; cd "$(dirname "$0")"
{ echo '/* jaack.css — bundle of tokens.css + components/*.css (generated by build.sh; edit the sources). */'; cat tokens.css components/base.css components/background.css components/glass.css components/topbar.css components/themeswitch.css components/chapter.css components/hero.css components/rows.css components/stats.css components/navpill.css components/tooltip.css; } > jaack.css
{ echo '// jaack.js — bundle of components/*.js except theme.js (generated by build.sh). Load with defer.'; cat components/background.js components/navpill.js components/tooltip.js components/sheet.js components/fade.js; } > jaack.js
echo "jaack.css $(wc -c < jaack.css) B, jaack.js $(wc -c < jaack.js) B"
